<template><ion-page><ion-header class="ion-no-border"><ion-toolbar><ion-buttons slot="start"><ion-back-button default-href="/app/more" /></ion-buttons><ion-title>Automation</ion-title></ion-toolbar></ion-header><ion-content><main class="page-wrap">
  <StatePanel v-if="loading" loading title="Loading controls" message="Checking current actuator state." /><StatePanel v-else-if="error" tone="danger" title="Unable to retrieve automation" :message="error" :retry="load" />
  <template v-else><div v-if="!canManage" class="info-note"><ion-icon :icon="informationCircleOutline" /><p>Your role has read-only farm access. Door and lighting commands require a Farm Owner or administrator.</p></div><article v-for="item in actuators" :key="item.id" class="control-card"><header><span :class="item.actuator_type"><ion-icon :icon="item.actuator_type === 'door' ? enterOutline : item.actuator_type === 'light' ? bulbOutline : nutritionOutline" /></span><div><p class="eyebrow">{{ titleCase(item.actuator_type) }}</p><h2>{{ item.device_name }}</h2></div><b>{{ titleCase(item.current_state) }}</b></header><p>Mode: {{ item.mode_display }} · Updated {{ relativeTime(item.last_changed_at) }}</p><div v-if="item.actuator_type !== 'feeder'" class="control-actions"><ion-button fill="outline" :disabled="!canManage || busy === item.id || item.current_state === offState(item)" @click="confirmControl(item, offState(item))">{{ offLabel(item) }}</ion-button><ion-button :disabled="!canManage || busy === item.id || item.current_state === onState(item)" @click="confirmControl(item, onState(item))">{{ onLabel(item) }}</ion-button></div></article><StatePanel v-if="!actuators.length" title="No actuators configured" message="Configure door and lighting controllers on the server first." /></template>
</main></ion-content></ion-page></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { alertController, IonBackButton, IonButton, IonButtons, IonContent, IonHeader, IonIcon, IonPage, IonTitle, IonToolbar } from '@ionic/vue'; import { bulbOutline, enterOutline, informationCircleOutline, nutritionOutline } from 'ionicons/icons'; import StatePanel from '@/components/StatePanel.vue'; import { automationService, type Actuator } from '@/services/automation.service'; import { relativeTime, titleCase } from '@/utils/format'; import { authState } from '@/stores/auth.store';
const actuators = ref<Actuator[]>([]); const loading = ref(true); const error = ref(''); const busy = ref<number>(); const canManage = computed(() => Boolean(authState.user?.permissions.manage_farm)); const onState = (item: Actuator) => item.actuator_type === 'door' ? 'open' : 'on'; const offState = (item: Actuator) => item.actuator_type === 'door' ? 'closed' : 'off'; const onLabel = (item: Actuator) => item.actuator_type === 'door' ? 'Open door' : 'Turn on'; const offLabel = (item: Actuator) => item.actuator_type === 'door' ? 'Close door' : 'Turn off';
async function load() { loading.value = true; error.value = ''; try { actuators.value = (await automationService.list()).results; } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to load controls.'; } finally { loading.value = false; } }
async function confirmControl(item: Actuator, state: string) { const alert = await alertController.create({ header: `${state === 'open' ? 'Open' : state === 'closed' ? 'Close' : 'Change'} ${item.device_name}?`, message: 'The command will be sent to the existing GoHMoTech controller.', buttons: [{ text: 'Cancel', role: 'cancel' }, { text: 'Confirm', role: 'confirm' }] }); await alert.present(); const result = await alert.onDidDismiss(); if (result.role !== 'confirm') return; busy.value = item.id; try { const response = await automationService.control(item.id, state); item.current_state = response.current_state; } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Command failed.'; } finally { busy.value = undefined; } } onMounted(load);
</script>
